def build():
    c = Chapter("5", "Mandatory Client Project Lifecycle",
                "Twenty-nine stages in five phases. For every stage this chapter states **tasks, owners, inputs, outputs, templates, review requirements and the approval gate**. "
                "No stage starts until the previous gate is signed.", search="lifecycle stage gate discovery requirements freeze sow architecture uat deployment handover maintenance")
    c.pills(["A Discover & Define (1–12)", "B Design & Plan (13–17)", "C Build (18–21)", "D Verify & Release (22–26)", "E Adopt & Sustain (27–29)"])
    c.h2("Approval gates at a glance")
    c.table(["Gate", "After stage", "Approver(s)", "Evidence required"], [
        ["G1 Qualification", "1", "Department Head", "Scorecard ≥ 18/25"],
        ["G2 Requirements freeze", "11", "Client sponsor, Department Head", "Signed BRD/FRS/NFR/I-O/permission matrix"],
        ["G3 Commercial approval", "12", "Department Head, client", "Signed SOW, margin ≥ target, advance received"],
        ["G4 Design approval", "13–15", "Technical Lead, client (UI)", "Architecture + ADRs, ERD, prototype signed"],
        ["G5 Ready to build", "16–17", "Technical Lead, PM", "Plan, protected repo, CI skeleton"],
        ["G6 Release candidate", "22", "QA Lead, Technical Lead", "No open critical/high defects; coverage targets"],
        ["G7 UAT sign-off", "23", "Client sponsor", "Signed UAT certificate"],
        ["G8 Go-live", "25", "Department Head, client", "Rehearsal passed, backup verified, rollback plan"],
        ["G9 Handover", "28", "Client, Department Head", "Handover pack and certificate"],
    ], widths=[22, 12, 30, 36])
    c.callout("tip", "Template codes",
              "**Appendices C–K** of this handbook contain the full text of the core templates (BRD, FRD, SOW, DB, QA, UAT, deployment, handover, costing). "
              "Codes **T01–T19** are template IDs reserved for the lighter working forms (scorecards, registers, minutes); they are **produced in Modules M1–M6** and are not yet written — until then, use the checklist in the stage's Tasks row.")
    n = 0
    for phase, stages in PHASES:
        c.h2(phase)
        for (title, owner, tasks, inp, outp, tmpl, review, gate) in stages:
            n += 1
            c.h3(f"Stage {n:02d} — {title}", toc=True)
            c.kv([("Owner", owner), ("Tasks", "\n".join(f"• {t}" for t in tasks)), ("Inputs", inp), ("Outputs", outp),
                  ("Templates", tmpl), ("Review", review), ("Approval gate", gate)])
    assert n == 29, n
    return [c]
